func assertAppliedMigrationChecksums(t *testing.T, db *DB, versions ...int64) {
	t.Helper()
	ctx := context.Background()
	sources, err := embeddedMigrations()
	if err != nil {
		t.Fatal(err)
	}
	for _, version := range versions {
		var applied int
		var expected, recorded string
		if err := db.QueryRowContext(ctx, `SELECT COUNT(*) FROM goose_db_version WHERE version_id=? AND is_applied=1`, version).Scan(&applied); err != nil || applied != 1 {
			t.Fatalf("migration %d applied rows = %d, %v; want 1", version, applied, err)
		}
		for _, source := range sources {
			if source.version == version {
				expected = source.checksum
				break
			}
		}
		if err := db.QueryRowContext(ctx, `SELECT sha256 FROM posse_migration_checksums WHERE version=?`, version).Scan(&recorded); err != nil || recorded != expected {
			t.Fatalf("migration %d checksum = %q, err=%v; want %q", version, recorded, err, expected)
		}
	}
}

package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"os"
)

// The unreleased vocabulary branch used 53 before main published Watch runtime
// and Task containment as 53/54. Only that exact receipt can move to 55.
const legacyVocabularyMigrationChecksum = "b974a5f9ae9d6341d5192d7217f552f0f2e673682992ad9c0e3449ff569779e3"

func (db *DB) normalizeLegacyVocabularyMigration(ctx context.Context) error {
	var ready int
	if err := db.QueryRowContext(ctx, `SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name IN ('goose_db_version','posse_migration_checksums')`).Scan(&ready); err != nil || ready != 2 {
		return err
	}
	var checksum string
	if err := db.QueryRowContext(ctx, `SELECT sha256 FROM posse_migration_checksums WHERE version=53`).Scan(&checksum); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil
		}
		return err
	}
	if checksum != legacyVocabularyMigrationChecksum {
		return nil
	}
	var applied, destination int
	if err := db.QueryRowContext(ctx, `SELECT COUNT(*) FROM goose_db_version WHERE version_id=53 AND is_applied=1`).Scan(&applied); err != nil {
		return err
	}
	if applied != 1 {
		return fmt.Errorf("legacy vocabulary migration has %d applied receipts, want 1", applied)
	}
	if err := db.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM goose_db_version WHERE version_id=55) OR EXISTS(SELECT 1 FROM posse_migration_checksums WHERE version=55)`).Scan(&destination); err != nil {
		return err
	}
	if destination != 0 {
		return fmt.Errorf("legacy vocabulary migration conflicts with version 55")
	}
	sources, err := embeddedMigrations()
	if err != nil {
		return err
	}
	found := false
	for _, source := range sources {
		if source.version == 55 {
			found = source.checksum == checksum
		}
	}
	if !found {
		return fmt.Errorf("vocabulary migration version 55 differs from its original contents")
	}
	if MigrationGate != nil {
		if err := MigrationGate(db.Path, []int64{53}, os.Getenv(ForceMigrationEnv) == "1"); err != nil {
			return err
		}
	}
	tx, err := db.beginTxWithRetry(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback()
	if _, err := tx.ExecContext(ctx, `UPDATE goose_db_version SET version_id=55 WHERE version_id=53`); err != nil {
		return err
	}
	if _, err := tx.ExecContext(ctx, `UPDATE posse_migration_checksums SET version=55 WHERE version=53 AND sha256=?`, checksum); err != nil {
		return err
	}
	return tx.Commit()
}

type migrationSource struct {
	version  int64
	checksum string
}

// embeddedMigrations hashes the migrations compiled into this build once.
var embeddedMigrations = sync.OnceValues(loadEmbeddedMigrations)

func loadEmbeddedMigrations() ([]migrationSource, error) {
	entries, err := fs.ReadDir(migrationFiles, "migrations")
	if err != nil {
		return nil, err
	}
	sources := []migrationSource{}
	for _, entry := range entries {
		name := entry.Name()
		if !strings.HasSuffix(name, ".sql") {
			continue
		}
		prefix, _, _ := strings.Cut(name, "_")
		version, err := strconv.ParseInt(prefix, 10, 64)
		if err != nil {
			return nil, fmt.Errorf("migration %s has no version prefix", name)
		}
		data, err := fs.ReadFile(migrationFiles, path.Join("migrations", name))
		if err != nil {
			return nil, err
		}
		sum := sha256.Sum256(data)
		sources = append(sources, migrationSource{version: version, checksum: hex.EncodeToString(sum[:])})
	}
	sort.Slice(sources, func(i, j int) bool { return sources[i].version < sources[j].version })
	return sources, nil
}

// schemaCurrent reports, using only reads, whether the database already holds
// exactly this build's migrations with matching checksums in WAL mode. Such a
// database needs no normalization, migration or checksum write, so opening it
// does not take the cross-process migration lock. Any doubt returns false.
func (db *DB) schemaCurrent(ctx context.Context, sources []migrationSource) bool {
	var journalMode string
	if err := db.QueryRowContext(ctx, "PRAGMA journal_mode").Scan(&journalMode); err != nil || !strings.EqualFold(journalMode, "wal") {
		return false
	}
	var tables int
	if err := db.QueryRowContext(ctx, `SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name IN ('goose_db_version','posse_migration_checksums')`).Scan(&tables); err != nil || tables != 2 {
		return false
	}
	applied, err := db.appliedMigrations(ctx)
	if err != nil || len(applied) != len(sources) {
		return false
	}
	rows, err := db.QueryContext(ctx, `SELECT version, sha256 FROM posse_migration_checksums`)
	if err != nil {
		return false
	}
	defer rows.Close()
	recorded := map[int64]string{}
	for rows.Next() {
		var version int64
		var checksum string
		if err := rows.Scan(&version, &checksum); err != nil {
			return false
		}
		recorded[version] = checksum
	}
	if rows.Err() != nil || len(recorded) != len(sources) {
		return false
	}
	for _, source := range sources {
		if !applied[source.version] || recorded[source.version] != source.checksum {
			return false
		}
	}
	return true
}

// checkSchema refuses a database this build does not know or that another
// build migrated differently, and asks MigrationGate before migrating an
// existing database. It runs under the migration lock, before goose.
func (db *DB) checkSchema(ctx context.Context, sources []migrationSource) error {
	var hasTable int
	if err := db.QueryRowContext(ctx, `SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name='posse_migration_checksums'`).Scan(&hasTable); err != nil {
		return err
	}
	if hasTable == 0 {
		if _, err := db.ExecContext(ctx, `CREATE TABLE IF NOT EXISTS posse_migration_checksums (version INTEGER PRIMARY KEY, sha256 TEXT NOT NULL)`); err != nil {
			return err
		}
	}
	applied, err := db.appliedMigrations(ctx)
	if err != nil {
		return err
	}
	recorded := map[int64]string{}
	rows, err := db.QueryContext(ctx, `SELECT version, sha256 FROM posse_migration_checksums`)
	if err != nil {
		return err
	}
	for rows.Next() {
		var version int64
		var checksum string
		if err := rows.Scan(&version, &checksum); err != nil {
			_ = rows.Close()
			return err
		}
		recorded[version] = checksum
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	if err := rows.Close(); err != nil {
		return err
	}
	forced := os.Getenv(ForceMigrationEnv) == "1"
	known := map[int64]string{}
	for _, source := range sources {
		known[source.version] = source.checksum
	}
	unknown, diverged := []string{}, []string{}
	for version := range applied {
		checksum, ok := known[version]
		if !ok {
			unknown = append(unknown, strconv.FormatInt(version, 10))
		} else if previous, ok := recorded[version]; ok && previous != checksum {
			diverged = append(diverged, strconv.FormatInt(version, 10))
		}
	}
	sort.Strings(unknown)
	sort.Strings(diverged)
	if len(unknown) > 0 && !forced {
		return &SchemaError{Code: "schema_unknown", Message: fmt.Sprintf("%s has migrations this posse build does not know: %s", db.Path, strings.Join(unknown, ", ")),
			Help: "Run the posse build that applied them (the installed `posse`), or set " + ForceMigrationEnv + "=1 to use this build anyway"}
	}
	if len(diverged) > 0 && !forced {
		return &SchemaError{Code: "schema_diverged", Message: fmt.Sprintf("%s was migrated by a posse build whose migrations %s differ from this build's", db.Path, strings.Join(diverged, ", ")),
			Help: "Run the posse build that applied them (the installed `posse`), or set " + ForceMigrationEnv + "=1 to use this build anyway"}
	}
	pending := []int64{}
	for _, source := range sources {
		if !applied[source.version] {
			pending = append(pending, source.version)
		}
	}
	if len(applied) > 0 && len(pending) > 0 && MigrationGate != nil {
